export function renderQualityMarkdown(report) {
  const lines = [
    '# Detection quality report',
    '',
    '<!-- Generated by scripts/measure-detection-quality.mjs --update-baseline; do not hand-edit. -->',
    '',
    `**Generated:** ${report.createdAt}`,
    `**Profile:** \`${report.profile}\``,
    `**Verdict:** ${report.verdict}`,
    '',
    '## Corpus',
    '',
    '| Metric | Count |',
    '|--------|------:|',
    `| Cases | ${report.corpus.caseCount} |`,
    `| Check decisions | ${report.corpus.decisionCount} |`,
    '',
    '## Language coverage',
    '',
    '| Language | Cases |',
    '|----------|------:|',
  ];
  for (const [language, count] of Object.entries(report.corpus.languages).sort()) {
    lines.push(`| \`${language}\` | ${count} |`);
  }
  lines.push(
    '',
    '## Per-check metrics',
    '',
    '| Check | Support | TP | FP | FN | TN | Precision | Recall | FPR | Languages |',
    '|-------|--------:|---:|---:|---:|---:|----------:|-------:|----:|-----------|',
  );
  for (const row of Object.values(report.metricsByCheck)) {
    lines.push(
      `| \`${row.slug}\` | ${row.support} | ${row.tp} | ${row.fp} | ${row.fn} | ${row.tn} | ${formatRate(row.precision)} | ${formatRate(row.recall)} | ${formatRate(row.fpr)} | ${Object.keys(
        row.languages,
      )
        .sort()
        .map((language) => `\`${language}\``)
        .join(', ')} |`,
    );
  }
  lines.push(
    '',
    '## Macro averages',
    '',
    '| Metric | Value | Checks |',
    '|--------|------:|-------:|',
    `| Precision | ${formatRate(report.macro.precision)} | ${report.macro.precisionChecks} |`,
    `| Recall | ${formatRate(report.macro.recall)} | ${report.macro.recallChecks} |`,
    `| FPR | ${formatRate(report.macro.fpr)} | ${report.macro.fprChecks} |`,
    '',
    '## Architecture triage usefulness',
    '',
    '| Metric | Value |',
    '|--------|------:|',
    `| Scenarios | ${report.architectureUsefulness.total} |`,
    `| Context changes decision | ${report.architectureUsefulness.contextChangesDecision} |`,
    `| Context does not change decision | ${report.architectureUsefulness.contextDoesNotChangeDecision} |`,
    `| Inconclusive | ${report.architectureUsefulness.inconclusive} |`,
    `| Decision-change rate | ${formatRate(report.architectureUsefulness.decisionChangeRate)} |`,
    '',
  );
  return `${lines.join('\n')}\n`;
}

export function markdownFingerprint(markdown) {
  return markdown.replace(/\*\*Generated:\*\* [^\n]+/, '**Generated:** <generated>').trim();
}

export function formatRate(value) {
  return value === null || value === undefined ? 'n/a' : value.toFixed(3);
}
